package com.typheye.wgpro.ui.function.device;
import android.database.Cursor; import android.os.Bundle; import android.view.*; import android.widget.TextView; import androidx.annotation.*; import androidx.fragment.app.Fragment; import com.typheye.wgpro.R; import com.typheye.wgpro.data.DeviceDatabase;
public class XiaomiDeviceFragment extends Fragment { public View onCreateView(@NonNull LayoutInflater i,ViewGroup p,Bundle b){View v=i.inflate(R.layout.fragment_device_detail,p,false);String id=requireActivity().getIntent().getStringExtra(DeviceDetailActivity.EXTRA_ID);Cursor c=new DeviceDatabase(requireContext()).get(id);if(c.moveToFirst()){String model=c.getString(c.getColumnIndexOrThrow("model"));((TextView)v.findViewById(R.id.detail_initial)).setText(model.substring(0,1).toUpperCase());((TextView)v.findViewById(R.id.detail_model)).setText(model);((TextView)v.findViewById(R.id.detail_kind)).setText("小米穿戴设备");((TextView)v.findViewById(R.id.detail_status)).setText("连接状态："+(c.getInt(c.getColumnIndexOrThrow("connected"))!=0?"已连接":"已断开"));((TextView)v.findViewById(R.id.detail_version)).setText("系统版本："+c.getString(c.getColumnIndexOrThrow("version")));((TextView)v.findViewById(R.id.detail_id)).setText("节点 ID："+id);String n=c.getString(c.getColumnIndexOrThrow("note"));((TextView)v.findViewById(R.id.detail_note)).setText(n==null||n.isEmpty()?"暂无备注":"备注："+n);}c.close();return v;} }
